/*
 * The vendor u-boot's pmu_sequence_config() (refs/u-boot-ums512,
 * arch/arm/cpu/armv8/sharkl5pro/pmu.c, "Sharkl5pro low power typical
 * parameter.xls 2019.05.08"), as the register writes it makes, in order.
 * u-boot ran it from board_init (sprd_pmu_lowpower_init -> CSP_Init) on
 * every stock boot; the cfw path skips u-boot, so the monitor does it.
 * It sets each power domain's power-on, sequence and isolation delays
 * (the reset values are far shorter: core 1 came up with an isolation delay
 * of 2 cycles instead of 9) and the PLL/crystal wait counts.
 *
 * Generated by compiling that function on the host against its
 * chip_sharkl5pro/pmu_apb.h with CHIP_REG_SET recording each write.
 */
